def mk(page,doc):
    L=List(page,doc,'baptist')
    raw=open(REPO+'src/content/pages/'+page).read()
    i=raw.find('scripture: ['); j=raw.find('\n  ],',i)
    L.pagerefs=[r for g in re.findall(r'"([A-Za-z0-9]+\.[0-9][^"]*)"',raw[i:j]) for r in g.split('+') if r]
    return L
def A(L,refs,work,loc,how,sent,ed,tag,printed=None,flag=None,url=None):
    for o in refs: L.add(o,work,loc,how,sent,ed,tag,url,printed,flag)
